        getChartData(state) {
            var labels = state.domainState.portfolioValueHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                portfolioValueChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.portfolioValueHistory.map(function(v) { return Math.round(v / 1000000 * 10) / 10; }) },
                        { data: state.domainState.cashHistory.map(function(v, i) {
                            var deployed = 100 - Math.round(v / 1000000 * 10) / 10;
                            return Math.round(deployed * 10) / 10;
                        }) }
                    ]
                },
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.financialScoreHistory },
                        { data: state.domainState.strategicScoreHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var totalScore = last.results ? last.results.totalScore || 0 : 0;
            var moic = last.results ? last.results.moic || 0 : 0;
            var irr = last.results ? last.results.projectedIRR || 0 : 0;
            var svs = last.results ? last.results.svs || 0 : 0;

            var performance = this._t('perf_developing');
            if (totalScore >= 160 && moic >= 2.0 && svs >= 70) performance = this._t('perf_elite');
            else if (totalScore >= 130 && moic >= 1.8) performance = this._t('perf_strong');
            else if (totalScore >= 100) performance = this._t('perf_competent');

            var insights = [];
            if (irr >= 15) insights.push(this._t('insight_irr_high'));
            else if (irr >= 12) insights.push(this._t('insight_irr_met'));
            else insights.push(this._t('insight_irr_low'));

            if (svs >= 65) insights.push(this._t('insight_svs_high'));
            else if (svs >= 45) insights.push(this._t('insight_svs_mid'));
            else insights.push(this._t('insight_svs_low'));

            if (moic >= 2.5) insights.push(this._t('insight_moic_high'));
            else if (moic < 1.5) insights.push(this._t('insight_moic_low'));

            return {
                totalScore: totalScore,
                moic: moic,
                projectedIRR: irr,
                svs: svs,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.moic < 1.0) return window.mySimulation.t('hint_low_moic');
            if (results.svs < 40 && state.currentPeriod >= 2) return window.mySimulation.t('hint_low_svs');
            if (results.financialScore > results.strategicScore + 30) return window.mySimulation.t('hint_imbalance_fin');
            if (results.strategicScore > results.financialScore + 30) return window.mySimulation.t('hint_imbalance_strat');
            if (state.domainState.cash < 20000000 && state.currentPeriod < 3) return window.mySimulation.t('hint_low_cash');
            if (results.newInvestments === 0) return window.mySimulation.t('hint_no_invest');
            return null;
        }

        getHistoryTableConfig() {
            return [
